package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type node struct {
	k    int64
	l, r *node
}

func insert(n *node, k int64) (*node, bool) {
	if n == nil {
		return &node{k: k}, true
	}
	var ok bool
	if k < n.k {
		n.l, ok = insert(n.l, k)
	} else if k > n.k {
		n.r, ok = insert(n.r, k)
	}
	return n, ok
}

func del(n *node, k int64) (*node, bool) {
	if n == nil {
		return nil, false
	}
	var ok bool
	if k < n.k {
		n.l, ok = del(n.l, k)
		return n, ok
	}
	if k > n.k {
		n.r, ok = del(n.r, k)
		return n, ok
	}
	if n.l == nil {
		return n.r, true
	}
	if n.r == nil {
		return n.l, true
	}
	s := n.r
	for s.l != nil {
		s = s.l
	}
	n.k = s.k
	n.r, _ = del(n.r, s.k)
	return n, true
}

func height(n *node) int {
	if n == nil {
		return 0
	}
	a, b := height(n.l), height(n.r)
	if a > b {
		return a + 1
	}
	return b + 1
}

func walk(n *node, out *[]string) {
	// iterative to avoid deep recursion issues
	var st []*node
	for n != nil || len(st) > 0 {
		for n != nil {
			st = append(st, n)
			n = n.l
		}
		n = st[len(st)-1]
		st = st[:len(st)-1]
		*out = append(*out, strconv.FormatInt(n.k, 10))
		n = n.r
	}
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	var root *node
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		var x int64
		if len(f) > 1 {
			x, _ = strconv.ParseInt(f[1], 10, 64)
		}
		switch f[0] {
		case "insert":
			var ok bool
			root, ok = insert(root, x)
			if ok {
				fmt.Fprintln(w, "ok")
			} else {
				fmt.Fprintln(w, "dup")
			}
		case "contains":
			n := root
			for n != nil && n.k != x {
				if x < n.k {
					n = n.l
				} else {
					n = n.r
				}
			}
			if n != nil {
				fmt.Fprintln(w, "yes")
			} else {
				fmt.Fprintln(w, "no")
			}
		case "delete":
			var ok bool
			root, ok = del(root, x)
			if ok {
				fmt.Fprintln(w, "ok")
			} else {
				fmt.Fprintln(w, "missing")
			}
		case "inorder":
			if root == nil {
				fmt.Fprintln(w, "<empty>")
			} else {
				var o []string
				walk(root, &o)
				fmt.Fprintln(w, strings.Join(o, " "))
			}
		case "height":
			fmt.Fprintln(w, height(root))
		case "min", "max":
			if root == nil {
				fmt.Fprintln(w, "empty")
			} else {
				n := root
				for {
					var nx *node
					if f[0] == "min" {
						nx = n.l
					} else {
						nx = n.r
					}
					if nx == nil {
						break
					}
					n = nx
				}
				fmt.Fprintln(w, n.k)
			}
		}
	}
}
